config.script:
// A2 "triagem_confirmacao" (#908) — agente tipo `script` (MACRO). Comportamento = ESTE arquivo (DADO).
// Reage à resposta do paciente e DESPACHA determinístico pelo PAYLOAD do botão (não por rótulo/idioma):
//   - botão com intent 'confirmar' -> confere que o agendamento do botão TOCADO é do paciente da
//                                     conversa, confirma + resolve o ticket;
//   - botão com intent 'ajuda'     -> joga pra fila humana (recepção);
//   - botão sem payload/desconhecido OU texto livre -> assume posse (dono-bot) e escala pro A1 (IA).
// Ticket PRIVADO (atendimento com um profissional, agentes#249): só confirma pelo botão e comenta —
// nunca atribui, não manda para a fila nem resolve; o resto fica com o profissional dono do ticket.
// Mudar isto = editar este .js + re-importar (sem rebuild do MS).
//
// Injetados: event ({subject, payload_safe}), config ({tipos_botao, botao_intents, escalar_agente,
// fila_humana}), context ({agente_id}), call(), log().

var subject = event.subject || {};
var payloadSafe = event.payload_safe || {};
var selfId = String(context.agente_id || '');
var conversaId = subject.conversa_id;
if (!conversaId) throw new Error('evento sem conversa_id — triagem não aplicável');
conversaId = String(conversaId);

var tiposBotao = (config.tipos_botao || ['button', 'interactive']).map(function (t) { return String(t).toLowerCase(); });
var botaoIntents = config.botao_intents || {};
var escalarAgente = config.escalar_agente;   // id do A1
if (!escalarAgente) throw new Error("config obrigatória ausente: 'escalar_agente'");
var filaHumana = config.fila_humana || 'atendente';

// --- helpers -----------------------------------------------------------------

function unwrap(r) { var b = (r && r.body) ? r.body : r; return (b && b.data !== undefined) ? b.data : b; }

// Ação CRÍTICA: TEM de suceder (senão vira false-success) — aborta o ramo (status=erro).
function callStrict(action, payload, oQue) {
  var r = call(action, payload);
  if (r && r.ok === false) throw new Error('ação crítica falhou (' + oQue + '): HTTP ' + (r.status_code));
  return r;
}

// Rehidrata a mensagem inbound MAIS RECENTE (a API devolve DESC; a 1ª 'in' é a mais nova).
function ultimaInbound() {
  var data = unwrap(call('ler_conversa', { conversa_id: conversaId, page: 1, per_page: 10 }));
  var msgs = (data && data.length !== undefined) ? data : (data && data.items ? data.items : null);
  if (!msgs || !msgs.length) return {};
  for (var i = 0; i < msgs.length; i++) { if (msgs[i] && msgs[i].direction === 'in') return msgs[i]; }
  return msgs[0] || {};
}

// Agendamento AMARRADO ao botão tocado (autoritativo): a mensageria correlaciona por context.id.
function agendamentoDaMensagem(msg) {
  if (msg && msg.referencia_tipo === 'agendamento' && msg.referencia_id) return String(msg.referencia_id);
  return null;
}

// Fallback: o agendamento do contexto do observador (1 por conversa, sobrescrito com vários convites).
function agendamentoDoEvento() {
  var obs = payloadSafe.observadores || [];
  for (var i = 0; i < obs.length; i++) {
    if (obs[i] && String(obs[i].id) === selfId) {
      var ctx = obs[i].contexto || {};
      if (ctx.agendamento_id) return String(ctx.agendamento_id);
    }
  }
  var ref = subject.agendamento_id || subject.referencia_id;
  return ref ? String(ref) : null;
}

function desinscreverSelf() {
  call('desinscrever_observador', { conversa_id: conversaId, observador_tipo: 'bot', observador_id: selfId });
}

// Ticket ATUAL da conversa (dono, paciente vinculado e privacidade), lido uma vez. Leitura que
// falhou = null: segue como ticket público (o comportamento anterior ao agentes#249).
function lerTicket() {
  var data = unwrap(call('obter_ticket', { conversa_id: conversaId }));
  return (data && data.ticket) ? data.ticket : null;
}

// #1608 H3: guardrail — há um operador HUMANO cuidando do ticket desta conversa AGORA?
// O arme deixou de ser suprimido no interacoes (recorrente também arma); a proteção "não
// auto-resolver um atendimento humano em curso" virou DECISÃO do agente: se um humano é dono
// do ticket, confirmamos o agendamento mas NÃO resolvemos por cima dele.
function ticketComDonoHumano() {
  return !!(ticket && ticket.responsavel_tipo === 'human' && ticket.responsavel_id);
}

// agentes#249 (revisão de segurança do interacoes#203): só confirma o agendamento do PACIENTE da
// conversa — o `cliente_id` do agendamento tem de ser o do ticket (o paciente vinculado ao contato).
// Contato sem vínculo ou agendamento que não deu para ler: não confirma, uma pessoa confere.
function conferirPaciente(agendamentoId) {
  var paciente = (ticket && ticket.cliente_id) ? String(ticket.cliente_id) : '';
  if (!paciente) return 'sem_vinculo';
  var r = call('buscar_agendamento', { id: agendamentoId });
  if (!r || r.ok === false) return 'indisponivel';
  var ag = unwrap(r);
  if (!ag || !ag.cliente_id) return 'indisponivel';
  return String(ag.cliente_id) === paciente ? 'ok' : 'outro_paciente';
}

var NOTA_NAO_CONFERIDO = {
  sem_vinculo: 'Paciente confirmou presença pelo botão, mas o contato não está vinculado a um paciente — confira se o agendamento é dele e confirme manualmente.',
  outro_paciente: 'Paciente tocou em confirmar, mas o agendamento do convite é de outro paciente — não confirmado. Confira.',
  indisponivel: 'Paciente confirmou presença pelo botão, mas não deu para conferir o agendamento agora — confira e confirme manualmente.'
};

// Passa a conversa para uma pessoa. Ticket público: fila humana (ação crítica) + nota. Ticket
// privado: fica com o profissional dono, só a nota (a fila recusaria com 409 ticket_privado).
function paraPessoa(nota, oQue) {
  if (!privado) callStrict('transferir_fila', { conversa_id: conversaId, fila: filaHumana }, oQue);
  call('comentar', { conversa_id: conversaId, conteudo: nota });
  desinscreverSelf();
}

// --- ramos -------------------------------------------------------------------

function ramoConfirmar(payloadBotao, msg) {
  var agendamentoId = agendamentoDaMensagem(msg) || agendamentoDoEvento();
  if (!agendamentoId) {
    // Botão 'sim' SEM agendamento vinculado (convite sem referência): não MENTE 'confirmado' nem
    // resolve às cegas — passa a uma pessoa pra confirmação manual (honesto).
    paraPessoa('Paciente confirmou presença pelo botão, mas o convite não trazia o agendamento vinculado — confira e confirme manualmente.',
      'transferir p/ fila humana (sim sem agendamento)');
    log('botão CONFIRMAR sem agendamento vinculado — passado a uma pessoa');
    return { ramo: 'confirmar_sem_agendamento', conversa_id: conversaId, payload_botao: payloadBotao, privado: privado };
  }
  var conferencia = conferirPaciente(agendamentoId);
  if (conferencia !== 'ok') {
    paraPessoa(NOTA_NAO_CONFERIDO[conferencia], 'transferir p/ fila humana (paciente não conferido)');
    log('botão CONFIRMAR — agendamento não conferido com o paciente da conversa (' + conferencia + ')');
    return { ramo: 'confirmar_nao_conferido', motivo: conferencia, conversa_id: conversaId, payload_botao: payloadBotao, privado: privado };
  }
  callStrict('confirmar_agendamento', { id: agendamentoId }, 'confirmar agendamento');
  // Ticket privado (agentes#249): confirma e deixa o atendimento com o profissional dono.
  if (privado) {
    call('comentar', { conversa_id: conversaId, conteudo: 'Paciente confirmou presença pelo botão. ✅ Agendamento confirmado. O atendimento privado segue com o profissional.' });
    desinscreverSelf();
    log('botão CONFIRMAR — agendamento confirmado; ticket privado mantido com o profissional');
    return { ramo: 'confirmar_sem_resolver', conversa_id: conversaId, payload_botao: payloadBotao, tem_agendamento: true, privado: true };
  }
  // Guardrail (#1608 H3): se um HUMANO cuida do ticket, confirma o agendamento mas NÃO
  // resolve por cima do atendimento humano em curso — deixa o ticket com o operador.
  if (ticketComDonoHumano()) {
    call('comentar', { conversa_id: conversaId, conteudo: 'Paciente confirmou presença pelo botão. ✅ Agendamento confirmado. Ticket mantido com o operador (atendimento humano em curso).' });
    desinscreverSelf();
    log('botão CONFIRMAR — agendamento confirmado; ticket preservado (dono humano ativo)');
    return { ramo: 'confirmar_sem_resolver', conversa_id: conversaId, payload_botao: payloadBotao, tem_agendamento: true, dono_humano: true };
  }
  call('comentar', { conversa_id: conversaId, conteudo: 'Paciente confirmou presença pelo botão. ✅ Agendamento confirmado automaticamente.' });
  call('resolver_ticket', { conversa_id: conversaId, nota: 'Confirmação de presença concluída automaticamente.' });
  desinscreverSelf();
  log('botão CONFIRMAR — agendamento confirmado + ticket resolvido (A2, por payload)');
  return { ramo: 'confirmar', conversa_id: conversaId, payload_botao: payloadBotao, tem_agendamento: true };
}

function ramoAjuda(payloadBotao) {
  if (privado) {
    paraPessoa('Paciente pediu ajuda pelo botão. 🆘 O atendimento privado segue com o profissional.', 'nota de ajuda (ticket privado)');
    log('botão AJUDA — ticket privado: nota para o profissional dono');
    return { ramo: 'ajuda', conversa_id: conversaId, payload_botao: payloadBotao, privado: true };
  }
  paraPessoa('Paciente pediu ajuda pelo botão. Encaminhado à recepção. 🆘', 'transferir p/ fila humana');
  log('botão AJUDA — encaminhado à fila humana (A2, por payload)');
  return { ramo: 'ajuda', conversa_id: conversaId, payload_botao: payloadBotao, fila: filaHumana };
}

function ramoEscala() {
  // Texto livre / botão não-reconhecido: escala pro A1 (LLM). Inscrever o A1 é o KICK do handoff.
  var agendamentoId = agendamentoDoEvento();
  callStrict('inscrever_observador', { conversa_id: conversaId, observador_tipo: 'bot', observador_id: escalarAgente, origem: 'automacao', contexto: { agendamento_id: agendamentoId } }, 'inscrever A1 (handoff)');
  call('atribuir_ticket', { conversa_id: conversaId, responsavel_id: escalarAgente, responsavel_tipo: 'bot' });
  call('comentar', { conversa_id: conversaId, conteudo: 'Resposta não-estruturada: escalado para a IA de confirmação.' });
  desinscreverSelf();
  return { ramo: 'escala', escalar_agente: escalarAgente, conversa_id: conversaId };
}

// --- fluxo -------------------------------------------------------------------

var ticket = lerTicket();
var privado = !!(ticket && ticket.privado);
var msg = ultimaInbound();
var tipo = String(msg.tipo || '').toLowerCase();
var ehBotao = tiposBotao.indexOf(tipo) !== -1;
var payloadBotao = String(msg.payload_botao || '').trim();

if (ehBotao && payloadBotao) {
  var intent = botaoIntents[payloadBotao];
  if (intent === 'confirmar') return ramoConfirmar(payloadBotao, msg);
  if (intent === 'ajuda') return ramoAjuda(payloadBotao);
  // payload de botão NÃO mapeado → cai no escalonamento (o A1 interpreta).
}

// Ticket privado (agentes#249): o agente não lê texto livre privado nem pode assumir o ticket
// (atribuir exige profissional + nota) — não interpreta; deixa a resposta com o profissional dono.
if (privado) {
  call('comentar', { conversa_id: conversaId, conteudo: 'Paciente respondeu ao convite de confirmação sem usar os botões. O atendimento privado segue com o profissional, que confirma se for o caso.' });
  desinscreverSelf();
  log('resposta não-estruturada em ticket privado — deixada com o profissional (sem escalar)');
  return { ramo: 'privado_com_profissional', conversa_id: conversaId, privado: true };
}

// Botão sem payload/desconhecido OU texto livre → assume posse (dono-bot) e escala pro A1.
call('atribuir_ticket', { conversa_id: conversaId, responsavel_id: selfId, responsavel_tipo: 'bot' });
return ramoEscala();

// A0 "armar_confirmacao" (#908) — agente tipo `script` (MACRO). Comportamento = ESTE arquivo (DADO).
// Arma a confirmação: quando o convite HSM sai, inscreve o A2 (triagem) como observador-bot da
// conversa, carimbando o agendamento no contexto. Mudar isto = editar este .js + re-importar (sem rebuild).
//
// Injetados pelo runtime: event (o gatilho), config (knobs/acoes), context (ids), call(), log().
//   event.payload_safe = { conversa_id?, cliente_id?, referencia_id? (=agendamento) }
//   config = { observar_agente (id do A2), ttl_seg }
//   call(action, payload) -> { ok, status_code, body }  (só ações curadas; RBAC do SA é a jaula)

var p = event.payload_safe || {};
var subj = event.subject || {};   // #fix: ids opacos (conversa_id/cliente_id/referencia) vêm no
                                  // subject SEM lint; o payload_safe pode perder um UUID (a
                                  // heurística de PII marca sequência de 11+/14 dígitos).
var observarAgente = config.observar_agente;   // id do A2 (resolvido de @triagem_confirmacao no import)
var ttlSeg = config.ttl_seg || 0;
var agendamentoId = subj.referencia_id || p.referencia_id || null;   // o agendamento do convite

// Preferência: o conversa_id já vem no evento `interacoes.template_enviado` (a conversa existe →
// inscreve direto, sem corrida). Fallback legado: resolve a conversa aberta pelo cliente.
var conversaId = subj.conversa_id || p.conversa_id;
if (!conversaId) {
  var clienteId = subj.cliente_id || p.cliente_id;
  if (!clienteId) { log('evento de envio sem conversa_id nem cliente_id — nada a armar'); return { status: 'sem_cliente' }; }
  var r = call('resolver_conversa', { cliente_id: clienteId });
  var data = (r && r.body && r.body.data) ? r.body.data : (r ? r.body : null);
  conversaId = (data && data[0] && data[0].id) ? String(data[0].id) : null;
}
if (!conversaId) { log('nenhuma conversa resolvível p/ armar'); return { status: 'sem_conversa' }; }
conversaId = String(conversaId);

var inscricao = {
  conversa_id: conversaId,
  observador_tipo: 'bot',
  observador_id: observarAgente,
  origem: 'automacao',
  contexto: { agendamento_id: agendamentoId ? String(agendamentoId) : null }
};
if (ttlSeg > 0) inscricao.expira_em = new Date(Date.now() + ttlSeg * 1000).toISOString();

call('inscrever_observador', inscricao);
log('A2 inscrito como observador da conversa (confirmação armada)');
return {
  status: 'armado',
  conversa_id: conversaId,
  observador_id: observarAgente,
  tem_agendamento: !!agendamentoId,
  ttl_seg: ttlSeg
};
